     <div hidden={inventoryView!=="stocktake"}><InventoryStocktake settings={data} costEdits={costEdits} setCostEdits={setCostEdits} rows={ledger} products={warehouse.products} busy={busy} edits={edits} setEdits={setEdits} onAction={paperAction} onError={setError} onMessage={setToast} onExport={rows=>download("仓库实物盘点模板.csv","\uFEFF"+rows.map(row=>row.map(csvCell).join(",")).join("\r\n"))}/></div>
