     <section className="panel order-review-panel"><OrderReviewFilters selected={orderFilters} counts={orderFilterIndex.counts} onChange={next=>{setOrderFilters(next);setOrderPage(1);}}/><div className="table-toolbar order-review-toolbar"><div className="search-field"><Search size={17}/><input aria-label="搜索订单" placeholder="搜索编码、规格、订单号或店铺" value={orderSearch} onChange={e=>{setOrderSearch(e.target.value);setOrderPage(1);}}/></div><span className="order-result-count">{[...MAIN_ORDER_FILTERS,...EXTRA_ORDER_FILTERS].filter(([id])=>orderFilters.includes(id)).map(([,label])=>label).join("、")} · {number(visibleOrders.length)} 条明细 · {number(visibleOrderCount)} 个订单</span>{orderFilters.length===1&&orderFilters[0]==="print"&&<button className="button secondary" onClick={()=>download("仓库打印清单.csv","\ufeff"+[["订单号","店铺","销售SKU","规格","数量（份）","ERP状态","打印说明","买家备注","卖家备注"],...visibleOrders.map(o=>[o.order_id,o.shop,o.code,o.spec,o.quantity,o.status,digitChoices.get(o.key)?.color,o.buyer_remark,o.seller_remark])].map(row=>row.map(csvCell).join(",")).join("\r\n"))}><Download size={15}/>导出打印清单</button>}</div>{visibleOrders.length?<div className="table-scroll"><table><thead><tr><th>商家编码 / 商品</th><th>店铺</th><th>状态</th><th className="numeric">销售数量</th><th className="numeric">已扣实物数量</th><th>下单 / 发货时间</th><th>操作</th></tr></thead><tbody>{visibleOrders.slice((currentOrderPage-1)*40,currentOrderPage*40).map(o=><tr key={o.key}><td><OrderIssue choice={isValid(o.status)||digitChoices.get(o.key)?.status==='print'?digitChoices.get(o.key):undefined}/><div className="order-identifiers"><code>{o.code||"未填编码"}</code>{o.order_id&&<code className="order-number">{o.order_id}</code>}</div><small>{o.spec}</small>{sourceDetails(o)&&<small>小红书：{sourceDetails(o)!.status} · {sourceDetails(o)!.after_sale}</small>}{(o.buyer_remark||o.seller_remark)&&<small>备注：{[o.buyer_remark,o.seller_remark].filter(Boolean).join("；")}</small>}{digitChoices.get(o.key)?.color&&<small>{digitChoices.get(o.key)?.status==="print"?"打印说明：":digitChoices.get(o.key)?.status==="pending"?"记录颜色（待确认）：":"发货颜色："}{digitChoices.get(o.key)?.color}</small>}</td><td>{o.shop}{sourceDetails(o)&&<small>小红书</small>}</td><td><Badge tone={isValid(o.status)?"green":"neutral"}>{o.status}</Badge>{reviewKeys.has(o.key)&&<small className="accent">{data.conflicts.some(c=>c.order_key===o.key)?"导入数据冲突":orderIssues.get(o.key)?orderIssues.get(o.key)!.label:cutoffTime(o,data.products,data.physical,data.rules)!=null?"待确认发货时间":sourceNeedsReview(o)?"小红书售后 / 发货待核对":"待核对退货 / 数量变化"}</small>}</td><td className="numeric">{number(o.quantity)}</td><td className="numeric">{paperTotals.has(o.key)?formatUnits(paperTotals.get(o.key)!):number(o.deducted_qty??0)+" "+(pmap.get(o.code)?.unit??"份")}</td><td>{date(o.order_time)}<small>{o.shipped_at?"发货："+time(o.shipped_at):"未提供发货时间"}</small></td><td><button className="text-btn" onClick={()=>void openReview(o.key)}>{reviewKeys.has(o.key)?"处理待核对":digitChoices.get(o.key)?.status==='print'?"查看 / 修改打印":"核对 / 退货"}</button></td></tr>)}</tbody></table></div>:<Empty title={!orderFilters.length?"请选择筛选条件":"没有符合筛选条件的订单"} detail={!orderFilters.length?"请选择上方订单分类。":"可调整筛选或搜索条件。新增订单请在首页点击“导入订单”。"}/>}<Pagination count={visibleOrders.length} page={currentOrderPage} size={40} setPage={setOrderPage}/></section>
     {unknown.length>0&&<details className="panel pending-products"><summary className="section-heading"><h2>订单中待补齐的商品<Badge tone="warm">{unknown.length} 项</Badge></h2><span className="muted">只需补建要囤货的商品 · 点击展开</span></summary><p className="pending-help">不囤货的商品可以暂不补建；已导入的订单和销量仍保留。需要管理库存时，再按商家编码补建 SKU 并盘点。</p><div className="table-toolbar"><div className="search-field"><Search size={17}/><input aria-label="搜索未匹配商品" placeholder="搜索未匹配编码或规格" value={unknownSearch} onChange={e=>{setUnknownSearch(e.target.value);setUnknownPage(1);}}/></div></div><div className="table-scroll"><table><thead><tr><th>商家编码</th><th>订单规格</th><th className="numeric">有效销售数量</th><th>操作</th></tr></thead><tbody>{unknownVisible.slice((unknownPage-1)*30,unknownPage*30).map((o,i)=><tr key={o.code+o.spec+i}><td><code>{o.code||"未填写商家编码"}</code></td><td><strong>{o.spec||o.title}</strong><small>{o.title.slice(0,60)}</small></td><td className="numeric">{number(o.qty)}</td><td><button className="text-btn" disabled={!o.code} onClick={()=>{navigate("products");setInventoryView("sales");setSearch(o.code);setToast("请点击右上角“新增销售SKU”，系统会带入这条订单的编码和规格。");}}>到库存管理处理<ArrowRight size={14}/></button></td></tr>)}</tbody></table></div><Pagination count={unknownVisible.length} page={unknownPage} size={30} setPage={setUnknownPage}/></details>}
